def aggregate(events, group_key):
    grouped = {}
    for event in events:
        key = event[group_key]
        grouped.setdefault(key, []).append(event["accuracy"])
    return {key: sum(values) / len(values) for key, values in grouped.items()}

events = [
    {"level": 9, "accuracy": 0.8},
    {"level": 9, "accuracy": 1.0},
    {"level": 8, "accuracy": 0.6},
]
avg_accuracy = aggregate(events, "level")

